using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = "";

    public string Category { get; set; } = "";

    [Required, MinLength(1)]
    public string Ingredients { get; set; } = "";

    [Required, MinLength(1)]
    public string Steps { get; set; } = "";

    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1½ cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together, then combine with dry mix.\n3. Heat a non-stick pan over medium heat.\n4. Pour ¼ cup batter per pancake.\n5. Flip when bubbles form on top. Cook until golden.",
                Ratings = [4, 5, 5, 4]
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice",
                Steps = "1. Toast the bread until golden and crisp.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread onto toast and sprinkle with red pepper flakes.",
                Ratings = [5, 4, 5]
            },
            new()
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner",
                Ingredients = "400g spaghetti\n200g pancetta or guanciale\n4 egg yolks\n1 cup Pecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp the pancetta in a skillet.\n3. Whisk egg yolks with grated cheese and pepper.\n4. Toss hot pasta with pancetta, remove from heat.\n5. Stir in egg mixture quickly to create a creamy sauce.",
                Ratings = [5, 5, 4, 5, 5]
            },
            new()
            {
                Id = 4, Title = "Chicken Stir-Fry", Category = "Dinner",
                Ingredients = "500g chicken breast, sliced\n2 cups mixed vegetables\n3 tbsp soy sauce\n1 tbsp sesame oil\n2 cloves garlic\n1 tbsp ginger\nRice for serving",
                Steps = "1. Heat sesame oil in a wok over high heat.\n2. Cook chicken until golden, set aside.\n3. Stir-fry garlic, ginger, and vegetables for 3 minutes.\n4. Return chicken, add soy sauce, toss to combine.\n5. Serve over steamed rice.",
                Ratings = [4, 4, 5]
            },
            new()
            {
                Id = 5, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n½ cup croutons\n¼ cup Parmesan\nCaesar dressing\nLemon wedge",
                Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Top with croutons and shaved Parmesan.\n4. Squeeze lemon over the top before serving.",
                Ratings = [4, 3, 4]
            },
            new()
            {
                Id = 6, Title = "Grilled Cheese Sandwich", Category = "Lunch",
                Ingredients = "2 slices white bread\n2 slices cheddar cheese\n1 tbsp butter",
                Steps = "1. Butter one side of each bread slice.\n2. Place cheese between the unbuttered sides.\n3. Grill on medium heat until golden on both sides and cheese melts.",
                Ratings = [5, 5, 4, 4]
            },
            new()
            {
                Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Ingredients = "2¼ cups flour\n1 cup butter, softened\n¾ cup sugar\n¾ cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips",
                Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix in flour and baking soda.\n4. Fold in chocolate chips.\n5. Drop spoonfuls onto baking sheet.\n6. Bake at 375°F for 9-11 minutes.",
                Ratings = [5, 5, 5, 5, 4]
            },
            new()
            {
                Id = 8, Title = "Banana Smoothie", Category = "Drinks",
                Ingredients = "2 ripe bananas\n1 cup milk\n½ cup yogurt\n1 tbsp honey\nIce cubes",
                Steps = "1. Add all ingredients to a blender.\n2. Blend until smooth.\n3. Pour into a glass and serve immediately.",
                Ratings = [4, 5, 4]
            },
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }
}

