@page "/"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>RecipeHub — Home</PageTitle>

<h1>🍳 Welcome to RecipeHub</h1>
<p class="lead">Discover and share your favorite recipes with our community.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h4 class="card-title">@CategoryIcon(category) @category</h4>
                    <p class="text-muted">@RecipeService.GetByCategory(category).Count recipe(s)</p>
                    <a href="category/@category" class="btn btn-outline-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryIcon(string category) => category switch
    {
        "Breakfast" => "🥞",
        "Lunch" => "🥗",
        "Dinner" => "🍝",
        "Desserts" => "🍪",
        "Drinks" => "🥤",
        _ => "🍽️"
    };
}

