@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes is null || recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span>@RenderStars(recipe.AverageRating) (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private List<RecipeHub.Models.Recipe>? recipes;

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (recipe is null)
{
    <p class="text-danger">Recipe not found.</p>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <h3 class="mt-4">Ingredients</h3>
    <ul class="list-group mb-4">
        @foreach (var line in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li class="list-group-item">@line</li>
        }
    </ul>

    <h3>Instructions</h3>
    <div class="mb-4">
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </div>

    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />

    <div class="mt-4">
        <a href="category/@recipe.Category" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-3 text-decoration-none"
                @onclick="() => Rate(star)"
                title="Rate @star star(s)">
            @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "★" : "☆")
        </button>
    }

    @if (submitted)
    {
        <span class="text-success ms-2">✓ Rated @selectedStar star(s)!</span>
    }
</div>

<p class="text-muted mt-1">
    @if (recipe is not null && recipe.Ratings.Count > 0)
    {
        <span>Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.Ratings.Count ratings)</span>
    }
    else
    {
        <span>No ratings yet — be the first!</span>
    }
</p>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedStar;
    private int hoveredStar;
    private bool submitted;
    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        recipe = RecipeService.GetById(RecipeId);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

<EditForm Model="recipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="recipe.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => recipe.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="recipe.Category" class="form-select">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Lunch">Lunch</option>
            <option value="Dinner">Dinner</option>
            <option value="Desserts">Desserts</option>
            <option value="Drinks">Drinks</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="recipe.Ingredients" class="form-control" rows="6"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => recipe.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="recipe.Steps" class="form-control" rows="6"
                       placeholder="1. Preheat oven to 350°F&#10;2. Mix ingredients&#10;3. Bake for 30 minutes" />
        <ValidationMessage For="() => recipe.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private Recipe recipe = new();

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(recipe.Category))
        {
            recipe.Category = "Dinner";
        }

        RecipeService.AddRecipe(recipe);
        Navigation.NavigateTo($"recipe/{recipe.Id}");
    }
}

