    @if (recipe is not null && recipe.Ratings.Count > 0)
    {
        <span>Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.Ratings.Count ratings)</span>
    }
    else
    {
        <span>No ratings yet — be the first!</span>
    }
</p>

